      final effect = XmlElement(
        localName: _kindToXml(transition.kind),
        prefix: 'p',
        namespaceUri: OfficeNamespaces.p,
      );
      if (transition.kind == PmlTransitionKind.fadeThroughBlack) {
        effect.setAttribute('thruBlk', '1');
